const reviewDueAutomationCeilings = `-- name: ReviewDueAutomationCeilings :many
SELECT c.id, c.automation_id, c.review_by, a.owner_user_id, a.name FROM pc.automation_ceilings c
JOIN pc.automations a ON a.org_id = c.org_id AND a.id = c.automation_id
WHERE c.org_id = $1 AND c.state = 'ACTIVE' AND c.review_by > now()
  AND c.review_by <= now() + make_interval(secs => $2::int)
ORDER BY c.review_by
LIMIT $3::int
`

type ReviewDueAutomationCeilingsRow struct {
	ID           ids.UUID
	AutomationID ids.UUID
	ReviewBy     time.Time
	OwnerUserID  ids.UUID
	Name         string
}

// Ceilings whose review date falls within the window (7-day and 1-day
// notices).
func (q *Queries) ReviewDueAutomationCeilings(ctx context.Context, orgID ids.OrgID, withinSeconds int32, maxRows int32) ([]ReviewDueAutomationCeilingsRow, error) {
	rows, err := q.db.Query(ctx, reviewDueAutomationCeilings, orgID, withinSeconds, maxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReviewDueAutomationCeilingsRow{}
	for rows.Next() {
		var i ReviewDueAutomationCeilingsRow
		if err := rows.Scan(
			&i.ID,
			&i.AutomationID,
			&i.ReviewBy,
			&i.OwnerUserID,
			&i.Name,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

